lesson.code:
class Produto {
public:
    string nome;
    double preco;
    int quantidade;
    Produto(string n, double p, int q) : nome(n), preco(p), quantidade(q) {}
};

class Estoque {
private:
    vector<Produto> produtos;
public:
    void adicionarProduto(const Produto &p) {
        produtos.push_back(p);
    }
    double valorTotal() const {
        double total = 0;
        for (const Produto &p : produtos) {
            total += p.preco * p.quantidade;
        }
        return total;
    }
};

int main() {
    Estoque loja;
    loja.adicionarProduto(Produto("Teclado", 150.0, 3));
    loja.adicionarProduto(Produto("Mouse", 80.0, 5));
    cout << "Valor total: " << loja.valorTotal();
}

